function save(){const j=JSON.stringify(KEYS());if(j===last)return;last=j;try{localStorage.setItem("sps",j)}catch(e){}clearTimeout(tm);tm=setTimeout(()=>dbRef&&dbRef.set({json:j,by:myId,ts:Date.now()}).then(()=>sync(1)).catch(()=>sync(0)),700)}
function openAppt(v){const [cb,h]=(v||"").split("|");let d=pd(S.ad);for(let i=0;i<7&&!slots(d).length;i++)d=new Date(d.getTime()+864e5);S.ap={m:"P",ds:fm(d),cb,h};apptUI()}
