function apptUI(){const q=S.ap,sl=slots(pd(q.ds));modal(`<h2>Agendar cita</h2><div class="seg1" style="margin-top:12px"><button class="sb ${q.m=="P"?"on":""}" data-a="apm" data-v="P">Cliente Premium</button><button class="sb ${q.m=="N"?"on":""}" data-a="apm" data-v="N">Nuevo cliente</button></div>${q.m=="P"?`<div class="fld"><label>Buscar cliente (antiguo)</label><input data-a="aq" placeholder="Nombre o teléfono"><select id="ac" style="margin-top:6px">${cOpts("")}</select></div>`:`<div class="g2"><div class="fld"><label>Nombre</label><input id="an"></div><div class="fld"><label>Apellido</label><input id="aa"></div></div><div class="fld"><label>Teléfono</label><input id="at" inputmode="tel"></div>`}<div class="fld"><label>Servicio</label><select id="as">${SV.map(x=>`<option>${x[0]}</option>`).join("")}</select></div><div class="g2"><div class="fld"><label>Fecha (dd/mm/aaaa)</label><input id="ad" data-a="adate" value="${q.ds}"></div><div class="fld"><label>Hora</label><select id="ah">${sl.length?sl.map(x=>`<option ${x==q.h?"selected":""}>${x}</option>`).join(""):`<option value="">Sin atención ese día</option>`}</select></div></div><div class="fld"><label>Camilla</label><select id="ab">${CAB9.map((c,i)=>`<option value="${i}" ${i==q.cb?"selected":""}>${c[0]}</option>`).join("")}</select></div><div style="display:flex;gap:8px"><button class="btn" style="flex:1" data-a="close2">Cancelar</button><button class="btn p" style="flex:1" data-a="saveappt">Agendar</button></div>`)}
function openBuy(){modal(`<h2>Registrar compra</h2><div style="margin-top:12px"><div class="fld"><label>Producto o insumo</label><select id="bi">${[...new Set(PR.map(x=>x[1]))].map(b=>`<optgroup label="${b}">${PR.map((x,i)=>x[1]==b?`<option value="p${i}">${x[0]}</option>`:"").join("")}</optgroup>`).join("")}<optgroup label="Insumos">${INS.map((x,i)=>`<option value="i${i}">${x[0]}</option>`).join("")}</optgroup></select></div><div class="g2"><div class="fld"><label>Cantidad</label><input id="bq" inputmode="numeric"></div><div class="fld"><label>Vence (opcional)</label><input id="bv" placeholder="MM/AAAA"></div></div></div><div style="display:flex;gap:8px"><button class="btn" style="flex:1" data-a="close2">Cancelar</button><button class="btn p" style="flex:1" data-a="savebuy">Sumar al inventario</button></div>`)}
