const pd=x=>{const [d,m,y]=x.split("/");return new Date(+y,m-1,+d)},fm=d=>p2(d.getDate())+"/"+p2(d.getMonth()+1)+"/"+d.getFullYear();
const gen=(a,b)=>{const t=x=>{const [h,m]=x.split(":");return +h*60+ +m},o=[];for(let x=t(a);x<=t(b);x+=30)o.push(p2(Math.floor(x/60))+":"+p2(x%60));return o};
const slots=d=>{const w=d.getDay();return w==1||w==3||w==5?[...gen("09:00","12:00"),...gen("15:00","20:00")]:w==2||w==4?gen("15:00","20:00"):w==6?gen("09:00","13:30"):[]};
