const face=i=>`<svg viewBox="0 0 24 24" width="44" height="44"><circle cx="12" cy="12" r="10.5" fill="${FACES[i][1]}"/><circle cx="8.5" cy="10" r="1.2" fill="#333"/><circle cx="15.5" cy="10" r="1.2" fill="#333"/><path d="${FACES[i][2]}" fill="none" stroke="#333" stroke-width="1.5" stroke-linecap="round"/></svg>`;
