const pcabs=i=>{const x=SV[i]||[];return x[3]=="Láser"?[6]:x[4]=="C"?[4,5]:[0,1,2,3]};
function planGen(p,n,start,gap,hour){const cb=pcabs(p.i),out=[];let d=pd(start);for(let k=0;k<n;k++){for(let g=0;g<70;g++){const sl=slots(d);if(sl.length){const h=sl.includes(hour)?hour:(sl.find(x=>x>=hour)||sl[sl.length-1]),ds=fm(d),cab=cb.find(c=>!S.appts.some(a=>a.d==ds&&a.cab==c&&a.h==h)&&!out.some(o=>o.d==ds&&o.cab==c&&o.h==h));if(cab!==undefined){out.push({d:ds,h,cab});break}}d=new Date(d.getTime()+864e5)}d=new Date(d.getTime()+864e5*gap)}return out}
const GAPS=[["Diaria",1],["3 por semana",2],["2 por semana",3],["Cada 5 días",5],["Semanal",7],["Cada 15 días",15],["Cada 21 días",21],["Mensual",30]];
function openPlan(j){const p=PKQ[j],nw=new Date();let hm=p2(nw.getHours())+":"+(nw.getMinutes()<30?"00":"30");if(hm<"09:00"||hm>"20:00")hm="15:00";const st=fm(new Date(nw.getTime()+864e5));S.pl={j,p,start:st,gap:7,hour:hm,rows:planGen(p,p.tot,st,7,hm)};planUI()}
function planUI(){const q=S.pl,c=S.clients.find(x=>x.id==q.p.c);modal(`<h2>Programar sesiones</h2><p class="help">${q.p.n} · ${q.p.tot} sesiones · ${c?c.n+" "+c.a:""}</p><div class="g2"><div class="fld"><label>Primera sesión</label><input id="pls" value="${q.start}"></div><div class="fld"><label>Frecuencia</label><select id="plg">${GAPS.map(g=>`<option value="${g[1]}" ${g[1]==q.gap?"selected":""}>${g[0]}</option>`).join("")}</select></div></div><div class="fld"><label>Hora preferida</label><select id="plh">${gen("09:00","20:00").map(h=>`<option ${h==q.hour?"selected":""}>${h}</option>`).join("")}</select></div><button class="btn" data-a="plgen" style="width:100%;margin-bottom:8px">Generar sesiones</button>${q.rows.map((w,i)=>`<div class="ln" style="display:flex;gap:6px;align-items:center"><b style="width:24px">${i+1}</b><input data-a="prd" data-id="${i}" value="${w.d}" style="min-width:0"><select data-a="prh" data-id="${i}" style="min-width:0">${gen("09:00","20:00").map(h=>`<option ${h==w.h?"selected":""}>${h}</option>`).join("")}</select><select data-a="prc" data-id="${i}" style="min-width:0">${pcabs(q.p.i).map(k=>`<option value="${k}" ${k==w.cab?"selected":""}>${CAB9[k][0]}</option>`).join("")}</select></div>`).join("")}<div style="display:flex;gap:8px;margin-top:12px"><button class="btn" style="flex:1" data-a="plprint">Imprimir</button><button class="btn p" style="flex:1" data-a="plsave">Guardar en agenda</button></div><button class="btn" style="width:100%;margin-top:8px" data-a="close2">Cerrar</button>`)}
